#include "tt.h"
#include <algorithm>
namespace rpsc {TranspositionTable::TranspositionTable(std::size_t mb){resize(mb);}void TranspositionTable::resize(std::size_t mb){std::size_t bytes=std::max<std::size_t>(1,mb)*1024*1024;std::size_t n=std::max<std::size_t>(1,bytes/sizeof(table_[0]));table_.assign(n,{});}void TranspositionTable::clear(){for(auto&c:table_)for(auto&e:c)e=TTEntry{};generation_=1;}const TTEntry*TranspositionTable::probe(Key k)const{if(table_.empty())return nullptr;auto&c=table_[std::size_t(k)%table_.size()];for(auto&e:c)if(e.bound!=Bound::None&&e.key==k)return &e;return nullptr;}void TranspositionTable::store(Key k,Depth d,Value v,Bound b,const Move*m){auto&c=table_[std::size_t(k)%table_.size()];TTEntry*slot=&c[0];for(auto&e:c){if(e.key==k){slot=&e;break;}int score=(e.bound==Bound::None?-100000:0)+e.depth*8+(e.generation==generation_?16:0);int best=(slot->bound==Bound::None?-100000:0)+slot->depth*8+(slot->generation==generation_?16:0);if(score<best)slot=&e;}if(slot->key==k&&slot->depth>d&&b!=Bound::Exact)return;slot->key=k;slot->depth=d;slot->value=v;slot->bound=b;slot->generation=generation_;if(m){slot->best_move=*m;slot->has_move=true;}else slot->has_move=false;}}
